    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private string? _message;

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    protected override void OnParametersSet()
    {
        if (Settings is not null && _settings != Settings)
        {
            _settings = Settings;
            _theme = _settings.Theme;
            _fontSize = _settings.FontSize;
            _language = _settings.Language;
            _compactMode = _settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _settings = updated;
        _message = "Appearance settings saved!";
        _saving = false;
    }

    private string GetPreviewClasses()
    {
        var classes = _theme == "Dark" ? "preview-dark" : "preview-light";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private string GetPreviewStyles()
    {
        var bgColor = _theme == "Dark" ? "#1e1e1e" : "#ffffff";
        var textColor = _theme == "Dark" ? "#e0e0e0" : "#212529";
        var fontSize = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.1rem",
            _ => "1rem"
        };

        return $"background-color: {bgColor}; color: {textColor}; font-size: {fontSize}; " +
               $"border-radius: 0 0 0.375rem 0.375rem; transition: all 0.2s ease; min-height: 200px;" +
               (_compactMode ? " padding: 0.5rem !important;" : "");
    }

    private string GetPreviewHeadingStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "1rem",
            "Large" => "1.4rem",
            _ => "1.2rem"
        };
        return $"font-size: {size};";
    }
}
