@using sv_e7d40fe706294620b355cb051c686084.Models
@namespace sv_e7d40fe706294620b355cb051c686084.Components.Pages.Settings

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (_settings is not null)
    {
        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title text-muted text-uppercase mb-3" style="font-size: 0.8rem;">Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title text-muted text-uppercase mb-3" style="font-size: 0.8rem;">Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title text-muted text-uppercase mb-3" style="font-size: 0.8rem;">Language</h6>
                        <select class="form-select" style="max-width: 300px;"
                                @bind="_language">
                            @foreach (var lang in Languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <!-- Compact Mode -->
                <div class="card mb-3">
                    <div class="card-body d-flex justify-content-between align-items-center">
                        <div>
                            <strong>Compact Mode</strong>
                            <br /><small class="text-muted">Reduce spacing and padding throughout the UI</small>
                        </div>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" checked="@_compactMode"
                                   @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
                        </div>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>

                @if (_message is not null)
                {
                    <div class="alert alert-success mt-3">@_message</div>
                }
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <strong>Preview</strong>
                    </div>
                    <div class="card-body preview-area @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h6 style="@GetPreviewHeadingStyle()">Sample Heading</h6>
                        <p style="margin-bottom: 0.5rem;">This is how your content will look with the selected settings.</p>
                        <div class="d-flex gap-2 mt-2">
                            <button class="btn btn-sm btn-primary">Primary</button>
                            <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                        </div>
                        <hr />
                        <ul style="padding-left: 1.2rem; margin-bottom: 0;">
                            <li>List item one</li>
                            <li>List item two</li>
                            <li>List item three</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private string? _message;

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    protected override void OnParametersSet()
    {
        if (Settings is not null && _settings != Settings)
        {
            _settings = Settings;
            _theme = _settings.Theme;
            _fontSize = _settings.FontSize;
            _language = _settings.Language;
            _compactMode = _settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _settings = updated;
        _message = "Appearance settings saved!";
        _saving = false;
    }

    private string GetPreviewClasses()
    {
        var classes = _theme == "Dark" ? "preview-dark" : "preview-light";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private string GetPreviewStyles()
    {
        var bgColor = _theme == "Dark" ? "#1e1e1e" : "#ffffff";
        var textColor = _theme == "Dark" ? "#e0e0e0" : "#212529";
        var fontSize = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.1rem",
            _ => "1rem"
        };

        return $"background-color: {bgColor}; color: {textColor}; font-size: {fontSize}; " +
               $"border-radius: 0 0 0.375rem 0.375rem; transition: all 0.2s ease; min-height: 200px;" +
               (_compactMode ? " padding: 0.5rem !important;" : "");
    }

    private string GetPreviewHeadingStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "1rem",
            "Large" => "1.4rem",
            _ => "1.2rem"
        };
        return $"font-size: {size};";
    }
}

